import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d

    if opp_d == 0:
        if n < 90:
            return 'C'
        return 'D'

    if opp_c == 0:
        return 'D'

    last_opp = opp[-1]
    recent = opp[-8:]
    recent_c = sum(1 for x in recent if x == 'C')
    recent_d = len(recent) - recent_c

    if n >= 95:
        return 'D' if opp_c * 2 >= n else 'C'

    if recent_d == 0:
        if n > 25 and opp_c * 100 >= n * 88:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    if recent_d >= 5:
        return 'D' if rng.random() < 0.9 else 'C'

    coop_rate = opp_c / n

    if coop_rate > 0.8:
        if last_opp == 'D':
            return 'C' if rng.random() < 0.45 else 'D'
        if recent_d <= 1:
            return 'C'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    if coop_rate > 0.5:
        if last_opp == 'D':
            if recent_c >= 5:
                return 'C'
            return 'D' if rng.random() < 0.75 else 'C'
        return 'C'

    if coop_rate > 0.25:
        if last_opp == 'D':
            return 'D' if rng.random() < 0.85 else 'C'
        if recent_d >= 2:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    if last_opp == 'D':
        return 'D' if rng.random() < 0.92 else 'C'
    return 'D' if rng.random() < 0.6 else 'C'
